import json, hashlib
from pathlib import Path

paths = [
    Path('.pi/co-math/attempt-research-plan-task-35.stdout.txt'),
    Path('.pi/co-math/attempt-research-plan-task-36.09b3808ea515.stdout.txt'),
]

def parse_complete_json(p):
    raw = p.read_bytes()
    if not raw:
        raise RuntimeError(f'FAIL-CLOSED: empty file: {p}')
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError as e:
        raise RuntimeError(f'FAIL-CLOSED: non-UTF-8 file {p}: {e}')
    dec = json.JSONDecoder()
    try:
        obj, end = dec.raw_decode(text.lstrip())
    except json.JSONDecodeError as e:
        raise RuntimeError(f'FAIL-CLOSED: invalid/truncated JSON in {p}: {e}')
    offset = len(text) - len(text.lstrip())
    if text[offset + end:].strip():
        raise RuntimeError(f'FAIL-CLOSED: trailing non-whitespace after JSON in {p}')
    return obj, hashlib.sha256(raw).hexdigest()

objs = []
for p in paths:
    obj, digest = parse_complete_json(p)
    objs.append(obj)
    print(json.dumps({'file': str(p), 'sha256': digest, 'top_type': type(obj).__name__, 'top_keys': sorted(obj) if isinstance(obj,dict) else None}, sort_keys=True))

# Print a bounded schema map, preserving all paths but replacing long scalar lists by type/length.
def schema(x, depth=0):
    if depth > 5:
        return {'type': type(x).__name__, 'truncated_schema': True}
    if isinstance(x, dict):
        return {str(k): schema(v, depth+1) for k,v in sorted(x.items(), key=lambda kv: str(kv[0]))}
    if isinstance(x, list):
        return {'type':'list','len':len(x),'items': [schema(v,depth+1) for v in x[:3]]}
    return {'type':type(x).__name__}
print(json.dumps({'schema_35':schema(objs[0]), 'schema_36':schema(objs[1])}, sort_keys=True, indent=2))

# Search recursively for likely matrix/product/family fields and emit exact values when modest-sized.
def walk(x, path='$'):
    if isinstance(x,dict):
        for k,v in x.items():
            yield from walk(v, path+'.'+str(k))
    elif isinstance(x,list):
        for i,v in enumerate(x):
            yield from walk(v, path+f'[{i}]')
    else:
        yield path,x
for k,obj in enumerate(objs,35):
    hits=[]
    def rec(x,path='$'):
        if isinstance(x,dict):
            for key,v in x.items():
                low=str(key).lower()
                if any(t in low for t in ('matrix','pieri','lr','family','zero','dimension','rank','digest','row','column','parameter','minor','complement')):
                    if isinstance(v,(str,int,float,bool)) or (isinstance(v,list) and len(v)<=30 and all(not isinstance(z,(dict,list)) for z in v)):
                        hits.append((path+'.'+str(key),v))
                rec(v,path+'.'+str(key))
        elif isinstance(x,list):
            for i,v in enumerate(x): rec(v,path+f'[{i}]')
    rec(obj)
    print(json.dumps({'certificate':k,'likely_fields':hits}, sort_keys=True, default=str, indent=2))
